import os
import requests

def validate_document_fields(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ.get("KLIPPA_API_KEY")
    if not api_key:
        raise ValueError("Missing Klippa API key. Set config['api_key'] or KLIPPA_API_KEY.")

    url = "https://custom-ocr.klippa.com/api/v1/parseDocument"
    required_fields = config.get("required_fields", [])
    minimum_confidence = float(config.get("minimum_confidence", 0.0))

    files = {}
    data = {}

    if isinstance(payload, str):
        if not os.path.exists(payload):
            raise FileNotFoundError(payload)
        files["document"] = open(payload, "rb")
    elif isinstance(payload, bytes):
        files["document"] = ("document.bin", payload)
    elif isinstance(payload, dict):
        if payload.get("file_path"):
            files["document"] = open(payload["file_path"], "rb")
        elif payload.get("file_bytes") is not None:
            filename = payload.get("filename", "document.bin")
            files["document"] = (filename, payload["file_bytes"])
        elif payload.get("url"):
            data["url"] = payload["url"]
        else:
            raise ValueError("payload dict must include one of: file_path, file_bytes, url")
    else:
        raise TypeError("payload must be a file path, bytes, or dict")

    if "document" not in files and "url" not in data:
        raise ValueError("No document source provided")

    headers = {"X-Auth-Key": api_key}
    try:
        response = requests.post(url, headers=headers, data=data, files=files or None, timeout=config.get("timeout", 60))
    finally:
        doc = files.get("document")
        if hasattr(doc, "close"):
            doc.close()
        elif isinstance(doc, tuple) and len(doc) > 1 and hasattr(doc[1], "close"):
            doc[1].close()

    response.raise_for_status()
    raw = response.json()
    parsed = raw.get("data", {}) if isinstance(raw, dict) else {}

    extracted = {}
    candidates = []

    if isinstance(parsed, dict):
        if isinstance(parsed.get("fields"), list):
            candidates.extend(parsed["fields"])
        if isinstance(parsed.get("result"), dict):
            for k, v in parsed["result"].items():
                if isinstance(v, dict):
                    candidates.append({"name": k, **v})
                else:
                    extracted[k] = {"value": v, "confidence": None}
        for k, v in parsed.items():
            if k in {"fields", "result"}:
                continue
            if isinstance(v, dict) and ("value" in v or "text" in v):
                candidates.append({"name": k, **v})

    for item in candidates:
        name = item.get("name") or item.get("label") or item.get("field")
        if not name:
            continue
        value = item.get("value", item.get("text"))
        confidence = item.get("confidence", item.get("score"))
        try:
            confidence = float(confidence) if confidence is not None else None
        except (TypeError, ValueError):
            confidence = None
        extracted[name] = {"value": value, "confidence": confidence}

    missing_required = [f for f in required_fields if f not in extracted or extracted[f].get("value") in (None, "", [])]
    low_confidence = {
        f: extracted[f]["confidence"]
        for f in required_fields
        if f in extracted
        and extracted[f].get("confidence") is not None
        and extracted[f]["confidence"] < minimum_confidence
    }

    result = {
        "provider": "Klippa OCR API",
        "valid": not missing_required and not low_confidence,
        "fields": extracted,
        "missing_required": missing_required,
        "low_confidence": low_confidence,
        "raw_response": raw,
    }
    return result
